<script setup lang="ts">
import axios from 'axios';
import {computed,defineAsyncComponent,h,onMounted,onUnmounted,ref,watch} from 'vue';
import {api,errorMessage} from '../api';
import {amount} from '../catalog';
import {quantity} from '../inventory';
import type {Business,Store} from '../types';
import AppDialog from './AppDialog.vue';
import AppIcon from './AppIcon.vue';
import type {ControlActivity,ControlReport,ControlSummary} from '../salesControl';
import {salesControlText as t} from '../locales/es/salesControl';
const SalesControlCharts=defineAsyncComponent({loader:()=>import('./SalesControlCharts.vue'),loadingComponent:{render:()=>h('p',{role:'status',class:'chart-loading'},t.chartsLoading)},delay:100});
const props=defineProps<{store?:Store;business:Business;compact?:boolean}>();const emit=defineEmits<{openOrder:[number];history:[]}>();
function localToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:props.business.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
const to=ref(localToday());const from=ref(to.value.slice(0,8)+'01');const query=ref('');const kind=ref('all');const state=ref('all');const report=ref<ControlReport|null>(null);const loading=ref(false);const error=ref('');const exporting=ref(false);const exportError=ref('');
const detailOpen=ref(false);const detailLoading=ref(false);const detailError=ref('');const detail=ref<ControlActivity|null>(null);const selected=ref<number|null>(null);const opener=ref<HTMLElement|null>(null);
let token=0;let detailToken=0;let controller:AbortController|undefined;let detailController:AbortController|undefined;let alive=true;
const root=computed(()=>`/business/stores/${props.store?.id}`);const dirty=computed(()=>loading.value||!report.value);const params=()=>({from:from.value,to:to.value,q:query.value,kind:kind.value,state:state.value});
const historyRows=computed(()=>props.compact?report.value?.data.slice(0,5):report.value?.data);
const tableMedia=window.matchMedia('(min-width:1200px)');const historyView=ref<'table'|'cards'>(tableMedia.matches?'table':'cards');let manualView=false;
function chooseView(mode:'table'|'cards'){historyView.value=mode;manualView=true;}
function resizeView(){if(!manualView)historyView.value=tableMedia.matches?'table':'cards';}
const status=(value:string)=>t.status[value]||value;
const method=(value:string)=>t.methods[value]||value;
const currencies=computed(()=>[...new Set([...(report.value?.summary.map(s=>s.currency)||[]),...(report.value?.cash.map(s=>s.currency)||[])])]);
const shortDate=(value:string)=>new Intl.DateTimeFormat(t.locale,{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(`${value}T00:00:00Z`));
const period=computed(()=>report.value?`${shortDate(report.value.filters.from)} — ${shortDate(report.value.filters.to)}`:'');
function metrics(s:ControlSummary){return [{key:'sales',label:t.metrics.sales,value:s.sales_net,note:t.invoices(s.invoices),icon:'cart'},{key:'unbilled',label:t.metrics.unbilled,value:s.unbilled_net,note:t.metrics.unbilledNote,icon:'bag'},{key:'paid',label:t.metrics.paid,value:s.paid_total,note:t.metrics.paidNote,icon:'document'},{key:'pending',label:t.metrics.pending,value:s.pending_total,note:t.metrics.pendingNote,icon:'document'}];}
function timestamp(value?:string){if(!value)return 0;return Date.parse(value.includes('T')?value:value.replace(' ','T')+'Z')||0;}
const activityDate=(value?:string)=>timestamp(value)?new Intl.DateTimeFormat(t.locale,{dateStyle:'medium',timeStyle:'short',timeZone:props.business.timezone}).format(new Date(timestamp(value))):t.unknownDate;
const timeline=computed(()=>{
    if(!detail.value)return [];const d=detail.value;const events:{key:string;type:string;label:string;reference:string;amount?:string;note:string;actor:string;date?:string}[]=[];
    for(const p of d.payments){events.push({key:`payment:${p.id}`,type:'payment',label:t.payment,reference:t.paymentReference(p.id),amount:p.amount,note:`${method(p.payment_method||'')} · ${status(p.status||'')}`,actor:'',date:p.paid_at});if(p.reversal_reason)events.push({key:`reversal:${p.id}`,type:'reversal',label:t.reversal,reference:t.paymentReference(p.id),amount:p.amount,note:p.reversal_reason,actor:p.reversal_actor||'',date:p.reversed_at});}
    for(const r of d.returns)events.push({key:`receipt:${r.sales_return_id}`,type:'receipt',label:t.receipt,reference:t.receiptReference(r.sales_return_id),note:r.reason,actor:r.actor_name,date:r.received_at});
    for(const r of d.returns)if(r.reversal)events.push({key:`receipt-reversal:${r.reversal.id}`,type:'reversal',label:t.receiptReversed,reference:t.receiptReference(r.sales_return_id),note:r.reversal.reason,actor:r.reversal.actor_name,date:r.reversal.created_at});
    for(const a of d.adjustments)events.push({key:`adjustment:${a.id}`,type:'adjustment',label:t.adjustment,reference:t.adjustmentReference(a.id),amount:a.amount,note:a.reason||'',actor:a.actor_name||'',date:a.created_at});
    for(const a of d.adjustments)if(a.reversal)events.push({key:`adjustment-reversal:${a.reversal.id}`,type:'reversal',label:t.adjustmentReversed,reference:t.adjustmentReference(a.id),amount:a.amount,note:a.reversal.reason,actor:a.reversal.actor_name,date:a.reversal.created_at});
    for(const c of d.credits)events.push({key:`credit:${c.id}`,type:'credit',label:c.target_order_id===d.order.id?t.incoming:t.outgoing,reference:t.creditReference(c.id),amount:c.amount,note:`${t.creditRoute(c.origin_order_id!,c.target_order_id!)} · ${c.reason||''}`,actor:c.actor_name||'',date:c.created_at});
    for(const c of d.credits)if(c.reversal)events.push({key:`credit-reversal:${c.reversal.id}`,type:'reversal',label:t.creditReversed,reference:t.creditReference(c.id),amount:c.amount,note:c.reversal.reason,actor:c.reversal.actor_name,date:c.reversal.created_at});
    for(const r of d.refunds)events.push({key:`refund:${r.id}`,type:'refund',label:t.refund,reference:t.refundReference(r.id),amount:r.amount,note:`${status(r.status||'')} · ${method(r.method||'')} · ${r.external_reference||t.noReference}`,actor:r.actor_name||'',date:r.refunded_at});
    for(const r of d.refunds)if(r.reversal)events.push({key:`refund-correction:${r.reversal.id}`,type:'reversal',label:t.refundCorrected,reference:t.refundReference(r.id),amount:r.amount,note:r.reversal.reason,actor:r.reversal.actor_name,date:r.reversal.created_at});
    return events.sort((a,b)=>timestamp(b.date)-timestamp(a.date));
});
async function load(page=1){if(!props.store)return;const version=++token;controller?.abort();controller=new AbortController();loading.value=true;error.value='';report.value=null;
    try{const result=await api.get(`${root.value}/sales/control`,{params:{...params(),page},signal:controller.signal});if(version===token){report.value=result.data;from.value=result.data.filters.from;to.value=result.data.filters.to;}}
    catch(e){if(version===token&&!axios.isCancel(e))error.value=errorMessage(e);}finally{if(version===token)loading.value=false;}}
function invalidate(){++token;controller?.abort();loading.value=false;report.value=null;error.value='';exportError.value='';}
function today(){from.value=localToday();to.value=from.value;void load();}
function month(){to.value=localToday();from.value=to.value.slice(0,8)+'01';void load();}
async function show(id:number,event?:Event){selected.value=id;opener.value=event?.currentTarget as HTMLElement|null;detailOpen.value=true;detail.value=null;detailError.value='';detailLoading.value=true;const version=++detailToken;detailController?.abort();detailController=new AbortController();
    try{const result=await api.get(`${root.value}/sales/orders/${id}/activity`,{signal:detailController.signal});if(version===detailToken)detail.value=result.data.data;}
    catch(e){if(version===detailToken&&!axios.isCancel(e))detailError.value=errorMessage(e);}finally{if(version===detailToken)detailLoading.value=false;}}
function close(){++detailToken;detailController?.abort();detailLoading.value=false;detailOpen.value=false;}
function operate(){const id=detail.value?.order.id;if(id){close();emit('openOrder',id);}}
async function exportCsv(){if(dirty.value||exporting.value)return;const version=token;exporting.value=true;exportError.value='';try{const response=await api.get(`${root.value}/sales/control/export`,{params:params(),responseType:'blob'});if(!alive||version!==token)return;if(!response.data.type.startsWith('text/csv'))throw new Error('Invalid CSV');const url=URL.createObjectURL(response.data);const a=document.createElement('a');a.href=url;a.download=t.exportFilename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){if(alive&&version===token)exportError.value=errorMessage(e);}finally{if(alive)exporting.value=false;}}
watch(()=>props.store?.id,()=>{close();void load();},{immediate:true});
onMounted(()=>tableMedia.addEventListener('change',resizeView));
onUnmounted(()=>{alive=false;++token;++detailToken;controller?.abort();detailController?.abort();tableMedia.removeEventListener('change',resizeView);});
</script>
<template>
<section class="sales-control" :aria-label="t.regions.control">
    <header class="control-heading"><div><h1>{{ compact?t.dashboardTitle:t.navigation }}</h1><p>{{ t.branchContext(store?.name||t.noStore,business.timezone) }}</p></div><div class="heading-actions"><span v-if="report" class="period-chip"><AppIcon name="document" />{{ period }}</span><div class="period-presets"><button type="button" @click="today">{{ t.today }}</button><button type="button" @click="month">{{ t.month }}</button></div></div></header>
    <div class="filters-panel">
        <form class="control-filters" @submit.prevent="load()"><label>{{ t.from }}<input v-model="from" type="date" required @input="invalidate"></label><label>{{ t.to }}<input v-model="to" type="date" required :min="from" @input="invalidate"></label><label class="search-filter">{{ t.search }}<div class="search-field"><AppIcon name="search"/><input v-model="query" type="search" maxlength="120" :placeholder="t.searchHint" @input="invalidate"></div></label><label>{{ t.kind }}<select v-model="kind" @change="invalidate"><option v-for="(label,value) in t.kinds" :key="value" :value="value">{{ label }}</option></select></label><label>{{ t.state }}<select v-model="state" @change="invalidate"><option v-for="(label,value) in t.states" :key="value" :value="value">{{ label }}</option></select></label><button type="submit" class="button primary apply-filters" :disabled="loading||!store"><AppIcon name="search"/>{{ t.apply }}</button></form>
        <details class="scope-help"><summary>{{ t.scopeTitle }}</summary><p>{{ t.scope }}</p></details>
        <p v-if="error" class="notice error" role="alert">{{ error }} <button type="button" class="button secondary" @click="load()">{{ t.retry }}</button></p><div v-if="loading" class="control-loading" role="status"><span class="loading-indicator"></span>{{ t.loading }}</div><p v-else-if="!report&&!error" class="notice">{{ t.changed }}</p>
    </div>
    <template v-if="report">
        <template v-if="compact">
        <section v-for="s in report.summary" :key="s.currency" class="indicator-section" :aria-label="t.regions.indicators(s.currency)">
            <div class="metric-grid"><article v-for="metric in metrics(s)" :key="metric.key" class="metric-card" :class="`metric-${metric.key}`"><div class="metric-top"><span>{{ metric.label }}</span><span class="metric-icon"><AppIcon :name="metric.icon"/></span></div><strong class="metric-value">{{ amount(metric.value,s.currency) }}</strong><p>{{ metric.note }}</p><span class="metric-accent"></span></article></div>
            <div class="secondary-metrics"><div><span>{{ t.metrics.net }}</span><strong>{{ amount(s.net_total,s.currency) }}</strong></div><div><span>{{ t.metrics.adjustments }}</span><strong>{{ amount(s.return_credit_total,s.currency) }}</strong></div><div><span>{{ t.metrics.credit }}</span><strong>{{ amount(s.credit_available,s.currency) }}</strong></div><div><span>{{ t.metrics.returns }}</span><strong :class="{attention:s.pending_returns>0}">{{ s.pending_returns }}</strong></div></div>
        </section>
        <section v-if="report.inventory" class="indicator-section inventory-valuation-section" aria-label="Valor del inventario">
            <div class="metric-grid">
                <article class="metric-card metric-paid">
                    <div class="metric-top"><span>Capital invertido en inventario</span><span class="metric-icon"><AppIcon name="inventory"/></span></div>
                    <strong class="metric-value">{{ amount(report.inventory.invested_cost, report.inventory.currency) }}</strong>
                    <p>Según precio de compra y existencia física{{ report.inventory.without_cost_variants > 0 ? ` (${report.inventory.without_cost_variants} sin costo registrado)` : '' }}</p>
                    <span class="metric-accent"></span>
                </article>
                <article class="metric-card metric-sales">
                    <div class="metric-top"><span>Valor del inventario en venta</span><span class="metric-icon"><AppIcon name="box"/></span></div>
                    <strong class="metric-value">{{ amount(report.inventory.sale_value, report.inventory.currency) }}</strong>
                    <p>Valor comercial a precio de venta actual</p>
                    <span class="metric-accent"></span>
                </article>
                <article class="metric-card metric-unbilled">
                    <div class="metric-top"><span>Ganancia proyectada</span><span class="metric-icon"><AppIcon name="document"/></span></div>
                    <strong class="metric-value">{{ amount(report.inventory.estimated_profit, report.inventory.currency) }}</strong>
                    <p>Diferencia entre valor de venta y capital invertido</p>
                    <span class="metric-accent"></span>
                </article>
                <article class="metric-card metric-pending">
                    <div class="metric-top"><span>Unidades en inventario</span><span class="metric-icon"><AppIcon name="warehouse"/></span></div>
                    <strong class="metric-value">{{ quantity(report.inventory.units_on_hand) }}</strong>
                    <p>Disponibles para vender: {{ quantity(report.inventory.units_available) }}</p>
                    <span class="metric-accent"></span>
                </article>
            </div>
        </section>
        <SalesControlCharts :daily="report.daily" :cash="report.cash" :currencies="currencies" :from="report.filters.from" :to="report.filters.to"/>
        </template>
        <template v-else><section v-for="s in report.summary" :key="s.currency" class="history-totals" :aria-label="t.regions.indicators(s.currency)"><div><span>{{ t.metrics.net }}</span><strong>{{ amount(s.net_total,s.currency) }}</strong></div><div><span>{{ t.applied }}</span><strong>{{ amount(s.paid_total,s.currency) }}</strong></div><div><span>{{ t.pending }}</span><strong>{{ amount(s.pending_total,s.currency) }}</strong></div><div><span>{{ t.metrics.orders }}</span><strong>{{ s.orders }}</strong></div></section></template>
        <section class="history-panel" :class="`history-view-${historyView}`" :aria-label="t.regions.history">
            <header class="history-heading"><div class="history-title"><span class="section-icon"><AppIcon name="document"/></span><div><h3>{{ compact?t.recentTitle:t.operationsTitle }}<span class="count-badge">{{ report.meta.total }}</span></h3><p>{{ compact?t.latest:t.historySubtitle }}</p></div></div><div class="history-tools"><div class="history-view-toggle" role="group" :aria-label="t.viewLabel"><button type="button" :aria-pressed="historyView==='table'" @click="chooseView('table')"><span aria-hidden="true">☷</span>{{ t.viewTable }}</button><button type="button" :aria-pressed="historyView==='cards'" @click="chooseView('cards')"><span aria-hidden="true">▦</span>{{ t.viewCards }}</button></div><button type="button" class="button secondary export-button" :disabled="exporting" @click="exportCsv"><span aria-hidden="true">↓</span>{{ t.export }}</button></div></header>
            <div class="history-context"><span class="context-dot"></span><span>{{ store?.name }}</span><span>{{ period }}</span><span>{{ t.kinds[kind] }}</span><span v-if="state!=='all'" class="filter-chip">{{ t.states[state] }}</span><span v-if="query" class="filter-chip">{{ query }}</span></div>
            <p v-if="exportError" class="notice error" role="alert">{{ exportError }}</p>
            <div v-if="report.data.length" class="history-table-wrap"><table class="history-table"><thead><tr><th>{{ t.columns.order }}</th><th>{{ t.columns.date }}</th><th>{{ t.columns.status }}</th><th>{{ t.columns.document }}</th><th class="numeric">{{ t.columns.net }}</th><th class="numeric">{{ t.columns.balance }}</th><th><span class="sr-only">{{ t.columns.action }}</span></th></tr></thead><tbody><tr v-for="row in historyRows" :key="row.id" :class="{excluded:['cancelled','draft'].includes(row.status)}"><td><div class="order-cell"><span class="customer-avatar">{{ row.customer_name.slice(0,1).toUpperCase() }}</span><div><strong>{{ row.customer_name }}</strong><small>{{ t.reference(row.kind,row.number) }}</small></div></div></td><td class="date-cell">{{ shortDate(row.created_at) }}</td><td><span class="state-badge" :class="`state-${row.status}`"><i></i>{{ status(row.status) }}</span><span v-if="row.return_pending" class="return-flag">{{ t.returnPending }}</span></td><td><span class="document-reference" :class="{muted:!row.invoice_number}">{{ row.invoice_number||t.noInvoice }}</span></td><td class="numeric"><strong class="table-money">{{ amount(row.net_total,row.currency) }}</strong><small v-if="row.return_credit_total!=='0.0000'" class="adjustment-caption">{{ t.adjustments }} {{ amount(row.return_credit_total,row.currency) }}</small><small v-if="['cancelled','draft'].includes(row.status)" class="excluded-caption">{{ t.excluded }}</small></td><td class="numeric"><span class="applied-money">{{ amount(row.paid_total,row.currency) }}</span><small class="pending-money" :class="{settled:row.pending_total==='0.0000'}">{{ row.pending_total==='0.0000'?t.paid:amount(row.pending_total,row.currency) }}</small></td><td><button type="button" class="row-action" :aria-label="t.detailAria(row.id)" :title="t.detail" @click="show(row.id,$event)"><span aria-hidden="true">↗</span></button></td></tr></tbody></table></div>
            <div class="history-cards"><article v-for="row in historyRows" :key="row.id" class="history-card" :class="{excluded:['cancelled','draft'].includes(row.status)}"><header><span class="order-reference">{{ t.reference(row.kind,row.number) }}</span><span class="state-badge" :class="`state-${row.status}`"><i></i>{{ status(row.status) }}</span></header><div class="card-customer"><span class="customer-avatar">{{ row.customer_name.slice(0,1).toUpperCase() }}</span><div><strong>{{ row.customer_name }}</strong><p>{{ shortDate(row.created_at) }}<span>·</span>{{ row.invoice_number||t.noInvoice }}</p></div></div><dl class="card-money"><div><dt>{{ t.net }}</dt><dd>{{ amount(row.net_total,row.currency) }}</dd></div><div><dt>{{ t.applied }}</dt><dd>{{ amount(row.paid_total,row.currency) }}</dd></div><div><dt>{{ t.pending }}</dt><dd class="pending-money">{{ amount(row.pending_total,row.currency) }}</dd></div></dl><p v-if="row.return_credit_total!=='0.0000'" class="card-adjustment">{{ t.original }} {{ amount(row.original_total,row.currency) }}<span>·</span>{{ t.adjustments }} {{ amount(row.return_credit_total,row.currency) }}</p><p v-if="row.return_pending" class="return-flag">{{ t.returnPending }}</p><p v-if="['cancelled','draft'].includes(row.status)" class="excluded-caption">{{ t.excluded }}</p><button type="button" class="card-detail" :aria-label="t.detailAria(row.id)" @click="show(row.id,$event)">{{ t.detail }}<span aria-hidden="true">↗</span></button></article></div>
            <div v-if="!report.data.length" class="history-empty"><span class="empty-symbol"><AppIcon name="search"/></span><h4>{{ t.emptyTitle }}</h4><p>{{ t.empty }}</p><small>{{ t.emptyHint }}</small></div>
            <footer class="history-footer"><span>{{ t.operationCount(report.meta.total) }}<small>{{ t.exclusions(report.summary.reduce((n,s)=>n+s.cancelled,0),report.summary.reduce((n,s)=>n+s.draft,0)) }}</small></span><button v-if="compact" type="button" class="button secondary" @click="emit('history')">{{ t.fullHistory }}<span aria-hidden="true">→</span></button><div v-else class="history-pagination"><button type="button" :disabled="report.meta.current_page<=1" @click="load(report.meta.current_page-1)">{{ t.previous }}</button><span>{{ t.page(report.meta.current_page,report.meta.last_page) }}</span><button type="button" :disabled="report.meta.current_page>=report.meta.last_page" @click="load(report.meta.current_page+1)">{{ t.next }}</button></div></footer>
        </section>
    </template>
</section>
<AppDialog :open="detailOpen" :title="t.detailTitle" :return-focus="opener" @close="close">
    <p v-if="detailLoading" role="status">{{ t.detailLoading }}</p><p v-if="detailError" class="notice error" role="alert">{{ detailError }} <button type="button" class="button secondary" @click="selected&&show(selected)">{{ t.detailRetry }}</button></p>
    <template v-if="detail"><div class="detail-identity"><span class="customer-avatar large">{{ detail.order.customer_snapshot.full_name.slice(0,1).toUpperCase() }}</span><div><span class="control-eyebrow">{{ t.reference(detail.order.order_kind||'sale',detail.order.basket_number||String(detail.order.id)) }}</span><h3>{{ detail.order.customer_snapshot.full_name }}</h3><p>{{ detail.order.invoice?.invoice_number||t.noInvoice }}<span>·</span><span class="state-badge" :class="`state-${detail.order.status}`">{{ status(detail.order.status) }}</span></p></div></div><div class="detail-metrics"><div><span>{{ t.net }}</span><strong>{{ amount(detail.order.net_total||detail.order.grand_total,detail.order.currency) }}</strong></div><div><span>{{ t.applied }}</span><strong>{{ amount(detail.order.paid_total,detail.order.currency) }}</strong></div><div><span>{{ t.pending }}</span><strong>{{ amount(detail.order.pending_total,detail.order.currency) }}</strong></div></div>
        <section class="detail-section" :aria-label="t.regions.items"><h3>{{ t.items }}</h3><article v-for="item in detail.order.items" :key="item.id" class="detail-item"><div><strong>{{ item.product_name_snapshot }}</strong><small>{{ item.sku_snapshot }}</small><p>{{ item.quantity }} × {{ amount(item.unit_price,detail.order.currency) }}</p></div><strong>{{ amount(item.line_total,detail.order.currency) }}</strong></article></section>
        <section class="detail-section"><h3>{{ t.timeline }}</h3><p class="timeline-note">{{ t.timelineNote }}</p><ol class="activity-timeline"><li v-for="event in timeline" :key="event.key" :class="`event-${event.type}`"><span class="timeline-marker"><AppIcon :name="event.type==='receipt'?'box':'document'"/></span><div class="event-body"><header><strong>{{ event.label }}</strong><strong v-if="event.amount" class="event-amount">{{ amount(event.amount,detail.order.currency) }}</strong></header><small>{{ event.reference }}<span>·</span>{{ activityDate(event.date) }}</small><p>{{ event.note }}</p><span v-if="event.actor" class="event-actor">{{ event.actor }}</span></div></li></ol><p v-if="!timeline.length" class="timeline-note">{{ t.noActivity }}</p></section>
    </template>
    <template #footer><button type="button" class="button secondary" @click="close">{{ t.detailClose }}</button><button v-if="detail" type="button" class="button primary" @click="operate">{{ t.operate }}<span aria-hidden="true">↗</span></button></template>
</AppDialog>
